  "nodes_info": [
    {
      "id": "1",
      "type": "start",
      "param": {
        "variables": [
          ["doc_list", "array[file]"]
        ]
      }
    },
    {
      "id": "2",
      "type": "iteration",
      "param": {
        "iterator_selector": ["doc_list", "1"],
        "output_selector": ["summary", "2-4"]
      }
    },
    {
      "id": "2-1",
      "type": "iteration-start",
      "param": {}
    },
    {
      "id": "2-2",
      "type": "document-extractor",
      "param": {
        "variable_selector": ["item", "2-1"]
      }
    },
    {
      "id": "2-3",
      "type": "llm",
      "param": {
        "system": "You are an expert document analyzer. Your task is to comprehensively parse the article structure, analyze the main content and function of each part, and provide a detailed summary.",
        "user": "Please analyze the following document:\n{{#'2-2'.text#}}\n\nProvide a comprehensive summary that includes:\n1. Document structure analysis\n2. Main content and purpose of each section\n3. Overall document summary"
      }
    },
    {
      "id": "2-4",
      "type": "template-transform",
      "param": {
        "variables": [
          ["doc_summary", ["text", "2-3"]]
        ],
        "template": "{{doc_summary}}"
      }
    },
    {
      "id": "3",
      "type": "template-transform",
      "param": {
        "variables": [
          ["summaries", ["output", "2"]]
        ],
        "template": "{% for summary in summaries %}Document {{loop.index}} Summary:\n{{summary}}\n\n{% endfor %}"
      }
    },
    {
      "id": "4",
      "type": "markdown-exporter",
      "param": {
        "target_type": "docx",
        "md_text": "{{#'3'.output#}}"
      }
    },
    {
      "id": "5",
      "type": "end",
      "param": {
        "outputs": [
          ["summary", ["output", "3"]],
          ["docx_file", ["files", "4"]]
        ]
      }
    }
  ],
  "edges": [
    ["1", 0, "2"],
    ["2", 0, "3"],
    ["2-1", 0, "2-2"],
    ["2-2", 0, "2-3"],
    ["2-3", 0, "2-4"],
    ["3", 0, "4"],
    ["4", 0, "5"]
  ]
}

