  "nodes_info": [
    {
      "id": "1",
      "type": "start",
      "param": {
        "variables": [
          ["source_code", "string"],
          ["case_input", "string"]
        ]
      }
    },
    {
      "id": "2",
      "type": "code",
      "param": {
        "variables": [
          ["code", ["source_code", "1"]]
        ],
        "outputs": [
          ["validated_code", "string"]
        ],
        "code": "import ast\n\ndef main(code: str):\n    try:\n        # Try to parse the code to check syntax\n        ast.parse(code)\n        # If parsing succeeds, return the original code\n        return {\"validated_code\": code}\n    except SyntaxError as e:\n        # If there's a syntax error, we'll let the LLM fix it\n        return {\"validated_code\": code}"
      }
    },
    {
      "id": "3",
      "type": "llm",
      "param": {
        "system": "You are a Python code validator and executor. Your tasks are:\n1. Check if the provided Python code is syntactically correct\n2. If there are syntax errors, fix them while preserving the intended functionality\n3. Execute the code with the provided input case\n4. Return ONLY the validated Python code and the execution result in the exact format specified",
        "user": "First, validate this Python code and fix any syntax errors:\n{{#2.validated_code#}}\n\nThen, execute the code with this input: {{#1.case_input#}}\n\nReturn your response in exactly this format:\n[PYTHON_CODE]\n<your validated python code here>\n[/PYTHON_CODE]\n\n[RESULT]\n<execution result here>\n[/RESULT]"
      }
    },
    {
      "id": "4",
      "type": "end",
      "param": {
        "outputs": [
          ["python_code", ["text", "3"]],
          ["result", ["text", "3"]]
        ]
      }
    }
  ],
  "edges": [
    ["1", 0, "2"],
    ["2", 0, "3"],
    ["3", 0, "4"]
  ]
}

