        "code": "import json
import base64

def main(contents_response: str, readme_response: str, base_url: str) -> dict:
    # Parse the contents API response
    try:
        contents_data = json.loads(contents_response)
    except json.JSONDecodeError:
        contents_data = []

    # Parse the README API response
    try:
        readme_data = json.loads(readme_response)
        # README content is base64 encoded
        if 'content' in readme_data:
            readme_content = base64.b64decode(readme_data['content']).decode('utf-8')
        else:
            readme_content = "README not found."
    except (json.JSONDecodeError, KeyError, base64.binascii.Error):
        readme_content = "Error retrieving README."

    # Function to build file structure tree
    def build_tree(items, indent=0):
        structure = ""
        if not isinstance(items, list):
            return f"Error: Unexpected data format: {type(items)}"

        # Sort items: directories first, then files, both alphabetically
        items.sort(key=lambda x: (x.get('type', '') != 'dir', x.get('name', '').lower()))

        for item in items:
            if isinstance(item, dict):
                name = item.get('name', 'Unknown')
                type = item.get('type', 'file')

                # Add to structure with proper indentation
                prefix = "│   " * indent
                structure += f"{prefix}├── {name}\n"

        return structure

    # Build the file structure
    file_structure = build_tree(contents_data)

    # Add header
    repo_name = base_url.split('/')[-2] + '/' + base_url.split('/')[-1].replace('/contents', '')
    result = f"Repository: {repo_name}\n" + "=" * (len(repo_name) + 12) + "\n" + file_structure

    return {
        "file_structure": result,
        "readme_content": readme_content
    }"
